const L='ABCDEF';
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length,opts};};
/* sentence choices keep their own final punctuation, so they are joined with a bar */
const chooseBar=(right,wrong,k)=>{const opts=[...wrong];opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(' | '),letter:L[opts.indexOf(right)],n:opts.length,opts};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
const cap=s=>s[0].toUpperCase()+s.slice(1);
