const PH=[['due to the fact that','because'],['in order to','to'],['at this point in time','now'],['in the event that','if'],['a large number of','many'],['has the ability to','can'],['for the purpose of','for'],['in spite of the fact that','although'],['each and every','each'],['at the present time','now']];
const fix=(s,only)=>{let n=0;return PH.reduce((t,[a,b])=>{const re=new RegExp(a,'i');if(!re.test(t)||(only&&n>=only))return t;n++;return t.replace(re,m=>m[0]===m[0].toUpperCase()?cap(b):b);},s);};
